export type PrismConfig = {
  theme: PrismTheme;
  darkTheme?: PrismTheme;
  defaultLanguage?: string;
  additionalLanguages: string[];
  magicComments: MagicCommentConfig[];
};

export class PrismHighlightSettings {
  private readonly prismTheme: PrismTheme;
  private readonly prismDarkTheme: PrismTheme | undefined;
  private readonly prismDefaultLanguage: string | undefined;
  private readonly prismAdditionalLanguages: string[];
  private readonly prismMagicComments: MagicCommentConfig[];

  constructor(config: PrismConfig) {
    this.prismTheme = config.theme;
    this.prismDarkTheme = config.darkTheme;
    this.prismDefaultLanguage = config.defaultLanguage;
    this.prismAdditionalLanguages = config.additionalLanguages;
    this.prismMagicComments = config.magicComments.map(
      (comment) => new MagicCommentDirective(comment),
    );
  }

  get theme(): PrismTheme {
    return this.prismTheme;
  }

  get darkTheme(): PrismTheme | undefined {
    return this.prismDarkTheme;
  }

  get defaultLanguage(): string | undefined {
    return this.prismDefaultLanguage;
  }

  get additionalLanguages(): string[] {
    return this.prismAdditionalLanguages;
  }

  get magicComments(): MagicCommentConfig[] {
    return this.prismMagicComments;
  }
}

export type FooterLinkItem = {
  label?: string;
  to?: string;
  href?: string;
  html?: string;
  prependBaseUrlToHref?: string;
} & {[key: string]: unknown};

export type FooterLogo = BaseLogo;

export type FooterBase = {
  style: 'light' | 'dark';
  logo?: FooterLogo;
  copyright?: string;
};

export type MultiColumnFooter = FooterBase & {
  links: {
    title: string | null;
    items: FooterLinkItem[];
  }[];
};

export type SimpleFooter = FooterBase & {
  links: FooterLinkItem[];
};

export type Footer = MultiColumnFooter | SimpleFooter;

export type TableOfContents = {
  minHeadingLevel: number;
  maxHeadingLevel: number;
};

// Theme config after validation/normalization
export type ThemeConfig = {
  docs: {
    versionPersistence: DocsVersionPersistence;
    sidebar: {
      hideable: boolean;
      autoCollapseCategories: boolean;
    };
  };

  // TODO we should complete this theme config type over time
  // and share it across all themes
  // and use it in the Joi validation schema?

  // TODO temporary types
  navbar: Navbar;
  colorMode: ColorModeConfig;
  announcementBar?: AnnouncementBarConfig;
  prism: PrismConfig;
  footer?: Footer;
  image?: string;
  metadata: {[key: string]: string}[];
  tableOfContents: TableOfContents;
};

// User-provided theme config, unnormalized
export type UserThemeConfig = DeepPartial<ThemeConfig>;

