      prism: {
        additionalLanguages: [],
        theme: darkTheme,
        magicComments: [
          {
            className: 'a',
            line: 'a-next-line',
          },
        ],
      },
    };
    expect(testValidateThemeConfig(prismConfig2)).toEqual({
      ...DEFAULT_CONFIG,
      ...prismConfig2,
    });
    const prismConfig3 = {
      prism: {
        additionalLanguages: [],
        theme: darkTheme,
        magicComments: [
          {
            className: 'a',
            block: {start: 'a-start', end: 'a-end'},
